-- Six outlet cohorts (venn-site #172). Additive: one nullable column (slides) plus six inserted rows; nothing existing is altered or dropped.
-- slides is a jsonb array of {title, body}; the portal slideshow renders it, falling back to company/goal/timeline when null.
alter table public.cohorts add column if not exists slides jsonb;

insert into public.cohorts (slug, name, company, goal, timeline, slides) values ('kinetic', 'Kinetic', 'Kinetic', 'Write about teens building real nonprofits, and publish a piece, with Venn coordinating.', 'Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off.', '[{"title":"What Kinetic is","body":"Kinetic is a small news site that tells the stories of high school builders. The tone is warm and quick, short profiles that take about two minutes to read."},{"title":"What it covers","body":"Teen-run nonprofits and the problems they chase, from climate and girls'' education to sports and community work."},{"title":"Sample headlines","body":"Pieces like \"The teen who decided climate science should speak every language\" and \"Why so many teenagers now run a 501(c)(3)\"."},{"title":"Your role","body":"You never have to contact Kinetic yourself. Venn is your facilitator: we set your goal with Kinetic as the sponsor, and we coordinate everything that comes after, by text from Venn''s number."},{"title":"The timeline","body":"Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off."},{"title":"Your first week","body":"Venn sets your first goal with Kinetic as the sponsor and texts it to you. You pick one young founder or nonprofit that interests you, and Venn handles the rest with the outlet."}]'::jsonb)
on conflict (slug) do nothing;

insert into public.cohorts (slug, name, company, goal, timeline, slides) values ('mercator-post', 'Mercator Post', 'Mercator Post', 'Cover student founders and startups across Asia, and publish a piece, with Venn coordinating.', 'Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off.', '[{"title":"What Mercator Post is","body":"Mercator Post is an editorial site about student founders building startups in China, Korea, Japan and across Asia. It reads a bit like a magazine for people who like numbers, calm and careful."},{"title":"What it covers","body":"Startups and early funding in Asia, the policy and visa rules that shape them, and the labs and schools where new companies begin."},{"title":"Sample headlines","body":"Pieces like \"The Lab Is the New Garage\" and \"Entry Requirements\", a look at Japan''s capital rule for business visas."},{"title":"Your role","body":"You never have to contact Mercator Post yourself. Venn is your facilitator: we set your goal with Mercator Post as the sponsor, and we coordinate everything that comes after, by text from Venn''s number."},{"title":"The timeline","body":"Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off."},{"title":"Your first week","body":"Venn sets your first goal with Mercator Post as the sponsor and texts it to you. You choose a company, market or rule change in Asia that you want to understand, and Venn handles the rest with the outlet."}]'::jsonb)
on conflict (slug) do nothing;

insert into public.cohorts (slug, name, company, goal, timeline, slides) values ('to-be-obsolete', 'To Be Obsolete', 'To Be Obsolete', 'Report on young people making serious money in unusual ways, and publish a piece, with Venn coordinating.', 'Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off.', '[{"title":"What To Be Obsolete is","body":"To Be Obsolete is a publication about young people making the standard path obsolete. It is sharp and full of real numbers, and it is not afraid of strange ways to earn."},{"title":"What it covers","body":"Markets and meme coins, founders, builders, creators and dropouts, anyone young who found a different route to real money."},{"title":"Sample headlines","body":"Pieces like \"The Lottery With a Leaderboard: Inside the Memecoin Generation\" and \"The Mansion Was the Product, Until the Lease Ran Out\"."},{"title":"Your role","body":"You never have to contact To Be Obsolete yourself. Venn is your facilitator: we set your goal with To Be Obsolete as the sponsor, and we coordinate everything that comes after, by text from Venn''s number."},{"title":"The timeline","body":"Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off."},{"title":"Your first week","body":"Venn sets your first goal with To Be Obsolete as the sponsor and texts it to you. You pick one person or market that fascinates you, and Venn handles the rest with the outlet."}]'::jsonb)
on conflict (slug) do nothing;

insert into public.cohorts (slug, name, company, goal, timeline, slides) values ('thebaytable', 'TheBayTable', 'TheBayTable', 'Write clear analysis of the business of technology, and publish a piece, with Venn coordinating.', 'Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off.', '[{"title":"What TheBayTable is","body":"TheBayTable is a weekly publication with analysis and commentary on the business of technology, written in a measured, serif-and-ink style."},{"title":"What it covers","body":"The companies, regulators and deals that shape tech, with a Bay Area point of view on what is happening this week."},{"title":"Sample headlines","body":"Pieces like \"Adobe, Figma and merger review\" and \"Instagram''s Teen Accounts\"."},{"title":"Your role","body":"You never have to contact TheBayTable yourself. Venn is your facilitator: we set your goal with TheBayTable as the sponsor, and we coordinate everything that comes after, by text from Venn''s number."},{"title":"The timeline","body":"Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off."},{"title":"Your first week","body":"Venn sets your first goal with TheBayTable as the sponsor and texts it to you. You choose a company or decision from this week''s tech news, and Venn handles the rest with the outlet."}]'::jsonb)
on conflict (slug) do nothing;

insert into public.cohorts (slug, name, company, goal, timeline, slides) values ('imperial-review', 'Imperial Review', 'Imperial Review', 'Learn and write about AI in a literary voice, and publish a piece, with Venn coordinating.', 'Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off.', '[{"title":"What Imperial Review is","body":"Imperial Review is a publication and network for young people who build with technology, written and edited by people. It reads like the news told as a good essay, a little poetic and never hype."},{"title":"What it covers","body":"How AI works and what it is doing to us, explained for readers who would rather be moved than lectured."},{"title":"Sample headlines","body":"Draft examples of the style: a plain explanation of how a language model learns, or an essay on what a machine cannot yet remember."},{"title":"Your role","body":"You never have to contact Imperial Review yourself. Venn is your facilitator: we set your goal with Imperial Review as the sponsor, and we coordinate everything that comes after, by text from Venn''s number."},{"title":"The timeline","body":"Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off."},{"title":"Your first week","body":"Venn sets your first goal with Imperial Review as the sponsor and texts it to you. You pick one idea about AI you want to explain in your own words, and Venn handles the rest with the outlet."}]'::jsonb)
on conflict (slug) do nothing;

insert into public.cohorts (slug, name, company, goal, timeline, slides) values ('yvette-labs', 'Yvette Labs', 'Yvette Labs', 'Explain how AI works in a French-flavored literary voice, and publish a piece, with Venn coordinating.', 'Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off.', '[{"title":"What Yvette Labs is","body":"Yvette Labs is a bilingual French and English editorial site about how AI works, for high school and college students. It is literary and unhurried, with a French sense of style."},{"title":"What it covers","body":"The ideas behind AI explained as essays, in a collection titled \"Comment meurent les belles choses\", with a manifesto on the way."},{"title":"Sample headlines","body":"The site is new, so these are draft examples of the style: a short essay on what a model actually knows, or a letter on translation and meaning."},{"title":"Your role","body":"You never have to contact Yvette Labs yourself. Venn is your facilitator: we set your goal with Yvette Labs as the sponsor, and we coordinate everything that comes after, by text from Venn''s number."},{"title":"The timeline","body":"Venn paces the weeks for you and texts you what is next. You will see exact dates once your cohort kicks off."},{"title":"Your first week","body":"Venn sets your first goal with Yvette Labs as the sponsor and texts it to you. You choose one idea about AI to explain in your own voice, and Venn handles the rest with the outlet."}]'::jsonb)
on conflict (slug) do nothing;

